// Fixed blue-six rule. No completed graph or target core as input.
use std::{collections::HashMap,io::{self,BufRead}};
fn ok(cs:&[Vec<usize>],miss:&[Vec<u64>],sel:&mut Vec<usize>)->bool{if cs.is_empty(){return true}for &i in &cs[0]{if sel.iter().all(|&j|miss[i].iter().zip(&miss[j]).all(|(a,b)|a&b==0)){sel.push(i);if ok(&cs[1..],miss,sel){return true}sel.pop();}}false}
struct Scan{a:Vec<u32>,b:Vec<u32>,p:Vec<usize>,gr:[u32;2],tri:Vec<u32>,lookup:HashMap<u32,usize>,miss:Vec<Vec<u64>>,ct:[usize;3],wins:Vec<Vec<usize>>}
impl Scan{fn run(&mut self,ls:&mut Vec<usize>,mask:u32){let n=ls.len();if n<5{let v=self.p[n];let d=4+self.p.iter().filter(|&&i|self.b[v]>>i&1==1).count() as u32;for i in 0..21{if mask>>i&1!=0||self.a[i].count_ones()!=d||(0..n).any(|j|self.a[i]>>ls[j]&1!=self.b[v]>>self.p[j]&1){continue}ls.push(i);self.run(ls,mask|1<<i);ls.pop();}return}self.ct[0]+=1;for (k,&g) in self.gr.iter().enumerate(){let mut cs=vec![];for v in 0..13{if g>>v&1==0{continue}let r=(0..5).filter(|&j|self.b[v]>>self.p[j]&1==1).fold(0,|x,j|x|1<<ls[j]);cs.push(self.tri.iter().filter(|&&s|s&mask==0).filter_map(|s|self.lookup.get(&(r|s)).copied()).collect::<Vec<_>>())}cs.sort_by_key(Vec::len);if !ok(&cs,&self.miss,&mut vec![]){return}self.ct[k+1]+=1}self.wins.push(ls.clone());}}
fn main(){for line in io::stdin().lock().lines(){let x:Vec<u32>=line.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let a=x[3..24].to_vec();let mut sets=vec![0u32];for i in 0..21{for j in 0..sets.len(){if sets[j]&a[i]==0{sets.push(sets[j]|1<<i)}}}let six:Vec<_>=sets.iter().copied().filter(|s|s.count_ones()==6).collect();let mut miss=vec![vec![0u64;(six.len()+63)/64];sets.len()];for(i,&s)in sets.iter().enumerate(){for(j,&q)in six.iter().enumerate(){if s&q==0{miss[i][j/64]|=1<<(j%64)}}}let mut r=Scan{a,b:x[24..].to_vec(),gr:[x[1],x[2]],p:(0..13).filter(|i|(x[1]|x[2])>>i&1==0).collect(),tri:sets.iter().copied().filter(|s|s.count_ones()==3).collect(),lookup:sets.into_iter().enumerate().map(|(i,s)|(s,i)).collect(),miss,ct:[0;3],wins:vec![]};r.run(&mut vec![],0);println!("{} {} {} {} {} {} {:?}",x[0],x[1],x[2],r.ct[0],r.ct[1],r.ct[2],r.wins)}}
